        image0 = np.array([[0, 1, 0], [1, 0, 1], [0, 1, 0]], dtype=np.float32)
        image1 = np.roll(image0, 1, axis=0)

        horizontal_flow, vertical_flow = horn_schunck(image0, image1, num_iter=100, alpha=0.1)

        expected_flow = np.array([[0, 0, 0], [0, 0, 0], [1, 1, 1]], dtype=np.float32)

